// BulkUploadPage.js
import React, { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";

/* ============================================================
   PARTICLES
============================================================ */
function FloatingParticles() {
    const [particles, setParticles] = useState([]);

    useEffect(() => {
        const generated = [...Array(55)].map(() => ({
            id: crypto.randomUUID(),
            left: Math.random() * 100,
            top: Math.random() * 100,
            delay: -(Math.random() * 15).toFixed(2),
            duration: 16 + Math.random() * 10,
        }));
        setParticles(generated);
    }, []);

    return (
        <div style={styles.particles}>
            {particles.map((p) => (
                <div
                    key={p.id}
                    style={{
                        ...styles.particle,
                        left: `${p.left}%`,
                        top: `${p.top}vh`,
                        animationDelay: `${p.delay}s`,
                        animationDuration: `${p.duration}s`,
                    }}
                />
            ))}
        </div>
    );
}

/* ============================================================
   TOAST
============================================================ */
function Toast({ message, type }) {
    return (
        <div
            style={{
                position: "fixed",
                top: "25px",
                left: "50%",
                transform: "translateX(-50%)",
                padding: "14px 22px",
                borderRadius: "10px",
                background:
                    type === "success"
                        ? "rgba(34,197,94,0.25)"
                        : "rgba(220,38,38,0.25)",
                color: type === "success" ? "#86efac" : "#fca5a5",
                border:
                    type === "success"
                        ? "1px solid rgba(34,197,94,0.55)"
                        : "1px solid rgba(220,38,38,0.55)",
                backdropFilter: "blur(6px)",
                boxShadow: "0 0 14px rgba(0,0,0,0.35)",
                zIndex: 9999,
            }}
        >
            {message}
        </div>
    );
}


/* ============================================================
   MAIN PAGE
============================================================ */
export default function BulkUploadPage() {
    const { studyId } = useParams();
    const navigate = useNavigate();

    const [zipFile, setZipFile] = useState(null);
    const [csvFile, setCsvFile] = useState(null);
    const [studyInfo, setStudyInfo] = useState(null);
    const [csvPreview, setCsvPreview] = useState(null);
    const [loading, setLoading] = useState(false);
    const [toast, setToast] = useState(null);

    // 💡 Help modal
    const [isHelpOpen, setIsHelpOpen] = useState(false);

    const showToast = (msg, type = "success") => {
        setToast({ msg, type });
        setTimeout(() => setToast(null), 3000);
    };

    /* ============================================================
       FETCH STUDY INFO
    ============================================================= */
    useEffect(() => {
        const fetchStudy = async () => {
            try {
                const res = await fetch(`http://localhost:8080/api/studies/${studyId}`);
                const data = await res.json();
                setStudyInfo(data);

                generateCsvFormat(data);
            } catch (e) {
                console.error(e);
            }
        };

        fetchStudy();
    }, [studyId]);

    /* ============================================================
       GENERATE CSV FORMAT PREVIEW AS TABLE
    ============================================================= */
    function generateCsvFormat(study) {
        if (!study) return;

        const artifactCount = study.artifactCountPerTask;
        const criteria = [...study.evaluationCriteria].sort(
            (a, b) => a.priorityOrder - b.priorityOrder
        );

        let columns = [];

        for (let i = 1; i <= artifactCount; i++) {
            columns.push(`artifact_${i}_filename`);
        }

        columns.push("question");
        columns.push("description");

        criteria.forEach((c) => {
            columns.push(`criterion_${c.priorityOrder}_${c.type}_answer`);
        });

        const exampleRow = columns.map((c) => `${c}_value`);

        setCsvPreview({
            headers: columns,
            row: exampleRow
        });
    }

    /* ============================================================
       SUBMIT HANDLER
    ============================================================= */
    const handleUpload = async () => {
        if (!zipFile || !csvFile) {
            showToast("Please select both ZIP and CSV files.", "error");
            return;
        }

        setLoading(true);

        try {
            const formData = new FormData();
            formData.append("zipFile", zipFile);
            formData.append("csvFile", csvFile);

            const res = await fetch(
                `http://localhost:8080/api/bulk/upload/${studyId}`,
                {
                    method: "POST",
                    headers: { Authorization: `Bearer ${localStorage.getItem("token")}` },
                    body: formData,
                }
            );

            const text = await res.text();

            if (res.ok) {
                showToast("Bulk upload completed successfully!", "success");

                setTimeout(() => {
                    navigate(`/manage-tasks/${studyId}`);
                }, 1800); // 1.8 saniye sonra otomatik geri dön
            }

            else showToast(text || "Bulk upload failed.", "error");
        } catch (e) {
            console.error(e);
            showToast("Upload failed: " + e.message, "error");
        }

        setLoading(false);
    };

    /* ============================================================
       HELPERS – CRITERIA / HELP MODAL
    ============================================================= */

    const sortedCriteria = studyInfo?.evaluationCriteria
        ? [...studyInfo.evaluationCriteria].sort(
            (a, b) => a.priorityOrder - b.priorityOrder
        )
        : [];

    const getCriterionTypeLabel = (type) => {
        switch (type) {
            case "MULTIPLE_CHOICE":
                return "Multiple Choice";
            case "RATING":
                return "Rating";
            case "OPEN_ENDED":
                return "Open-Ended";
            case "NUMERIC":
                return "Numeric";
            case "CODE_EDIT":
                return "Code Edit";
            case "IMAGE_HIGHLIGHT":
                return "Image Highlight";
            default:
                return type || "Unknown";
        }
    };

    const getCriterionTypeIcon = (type) => {
        switch (type) {
            case "MULTIPLE_CHOICE":
                return "✅";
            case "RATING":
                return "⭐";
            case "OPEN_ENDED":
                return "✏️";
            case "NUMERIC":
                return "🔢";
            case "CODE_EDIT":
                return "💻";
            case "IMAGE_HIGHLIGHT":
                return "🖼️";
            default:
                return "📋";
        }
    };

    const renderCriterionHelpRow = (crit) => {
        const colName = `criterion_${crit.priorityOrder}_${crit.type}_answer`;

        let exampleValue = "";
        let explanation = "";

        switch (crit.type) {
            case "MULTIPLE_CHOICE":
                exampleValue =
                    crit.multipleSelection && crit.options?.length >= 2
                        ? `"${crit.options[0]},${crit.options[1]}"`
                        : `"${crit.options?.[0] || "A"}"`;
                explanation = crit.multipleSelection
                    ? "Multiple selection: use quotes and comma-separated options, e.g. \"A,B\"."
                    : "Single selection: write one option, e.g. A (quotes optional).";
                break;

            case "RATING":
                exampleValue = `"${crit.startValue ?? 1}"`;
                explanation = `Numeric rating between ${crit.startValue} and ${crit.endValue}, e.g. 3.`;
                break;

            case "OPEN_ENDED":
                exampleValue = "\"Clear variable naming and small methods\"";
                explanation =
                    "Free-text reference answer. Optional — can be left empty if you don't use auto-comparison.";
                break;

            case "NUMERIC":
                exampleValue = crit.integerOnly ? `"42"` : `"3.14"`;
                explanation = crit.integerOnly
                    ? "Numeric answer (integer), e.g. 42."
                    : "Numeric answer (integer or decimal), e.g. 3.14.";
                break;

            case "CODE_EDIT":
                exampleValue = "\"Fixed version compiles without warnings\"";
                explanation =
                    "Optional free-text note about the ideal code change. Currently stored as plain text.";
                break;

            case "IMAGE_HIGHLIGHT":
                exampleValue = "\"[{\\\"x\\\":0.32,\\\"y\\\":0.12},{\\\"x\\\":0.55,\\\"y\\\":0.44}]\"";
                explanation =
                    "Store expected highlight locations as a JSON-like array of normalized coordinates. Entire value must be quoted.";
                break;

            default:
                exampleValue = "";
                explanation = "";
        }

        return (
            <div key={crit.id} style={styles.helpRow}>
                <div style={styles.helpRowHeader}>
                    <span style={styles.helpPill}>
                        {getCriterionTypeIcon(crit.type)}{" "}
                        {getCriterionTypeLabel(crit.type)} (priority {crit.priorityOrder})
                    </span>
                    <span style={styles.helpColumnName}>
                        Column: <code>{colName}</code>
                    </span>
                </div>
                {crit.question && (
                    <div style={styles.helpQuestion}>
                        Q: <span>{crit.question}</span>
                    </div>
                )}
                <div style={styles.helpExampleRow}>
                    <span style={styles.helpExampleLabel}>Example value:</span>
                    <code style={styles.helpExampleCode}>{exampleValue}</code>
                </div>
                <div style={styles.helpExplanation}>{explanation}</div>
            </div>
        );
    };

    /* ============================================================
       RENDER
    ============================================================= */
    return (
        <div style={styles.container}>
            <FloatingParticles />

            {/* NAVBAR */}
            <div style={styles.navbar}>
                <h2 style={styles.navTitle}>Bulk Upload — Study #{studyId}</h2>

                <div style={styles.navRight}>
