                            e.currentTarget.style.transform = "scale(1.05)";
                            e.currentTarget.style.boxShadow =
                                "0 0 16px rgba(234,179,8,0.6)";
                        }}
                        onMouseLeave={(e) => {
                            e.currentTarget.style.transform = "scale(1)";
                            e.currentTarget.style.boxShadow =
                                "0 0 10px rgba(234,179,8,0.35)";
                        }}
                        onClick={() => setIsHelpOpen(true)}
                    >
                        💡 CSV Help
                    </button>

                    <button
                        style={styles.backButton}
                        onMouseEnter={(e) => {
                            e.currentTarget.style.transform = "scale(1.05)";
                            e.currentTarget.style.boxShadow =
                                "0 0 18px rgba(220,38,38,0.7)";
                        }}
                        onMouseLeave={(e) => {
                            e.currentTarget.style.transform = "scale(1)";
                            e.currentTarget.style.boxShadow =
                                "0 0 12px rgba(220,38,38,0.4)";
                        }}
                        onClick={() => navigate(`/manage-tasks/${studyId}`)}
                    >
                        ← Back
                    </button>
                </div>
            </div>

            <div style={styles.centerWrapper}>

                {/* ---------------- CSV FORMAT TABLE ---------------- */}
                {csvPreview && (
                    <div style={styles.infoCard}>
                        <h3 style={styles.infoTitle}>📄 CSV Format Guide</h3>

                        <p style={styles.infoText}>
                            • This study requires <b>{studyInfo?.artifactCountPerTask}</b> artifact(s) per task.<br />
                            • There are <b>{studyInfo?.evaluationCriteria.length}</b> criteria.<br />
                            • Each row in the CSV file creates <b>one evaluation task</b> in this study.
                        </p>

                        <table style={styles.csvTable}>
                            <thead>
                            <tr>
                                {csvPreview.headers.map((h, i) => (
                                    <th key={i} style={styles.th}>{h}</th>
                                ))}
                            </tr>
                            </thead>
                            <tbody>
                            <tr>
                                {csvPreview.row.map((v, i) => (
                                    <td key={i} style={styles.td}>{v}</td>
                                ))}
                            </tr>
                            </tbody>
                        </table>
                    </div>
                )}

                {/* ---------------- UPLOAD CARD ---------------- */}
                <div style={styles.card}>
                    <h2 style={styles.cardTitle}>📦 Upload ZIP + CSV</h2>
                    <p style={styles.cardDesc}>
                        The ZIP contains artifacts.<br />
                        The CSV defines tasks + mapping + correct answers.
                    </p>

                    <div style={styles.inputGroup}>
                        <label style={styles.label}>ZIP File</label>
                        <input
                            type="file"
                            accept=".zip"
                            onChange={(e) => setZipFile(e.target.files[0])}
                            style={styles.fileInput}
                        />
                    </div>

                    <div style={styles.inputGroup}>
                        <label style={styles.label}>CSV File</label>
                        <input
                            type="file"
                            accept=".csv"
                            onChange={(e) => setCsvFile(e.target.files[0])}
                            style={styles.fileInput}
                        />
                    </div>

                    <button
                        style={styles.uploadButton}
                        onMouseEnter={(e) => {
                            e.currentTarget.style.transform = "scale(1.05)";
                            e.currentTarget.style.boxShadow =
                                "0 0 18px rgba(34,197,94,0.6)";
                        }}
                        onMouseLeave={(e) => {
                            e.currentTarget.style.transform = "scale(1)";
                            e.currentTarget.style.boxShadow =
                                "0 0 12px rgba(34,197,94,0.35)";
                        }}
                        disabled={loading}
                        onClick={handleUpload}
                    >
                        {loading ? "Uploading..." : "📤 Start Upload"}
                    </button>
                </div>
            </div>

            {toast && <Toast message={toast.msg} type={toast.type} />}

            {/* 💡 HELP MODAL */}
            {isHelpOpen && (
                <>
                    <div
                        style={styles.modalOverlay}
                        onClick={() => setIsHelpOpen(false)}
                    />
                    <div style={styles.modalWrapper}>
                        <div style={styles.modal}>
                            <div style={styles.modalHeader}>
                                <div>
                                    <h2 style={styles.modalTitle}>CSV Help & Examples</h2>
                                    <p style={styles.modalSubtitle}>
                                        This guide is generated from your study’s criteria. Each row in the CSV must follow this structure.
                                    </p>
                                </div>
                                <button
                                    style={styles.modalCloseButton}
                                    onClick={() => setIsHelpOpen(false)}
                                >
                                    ✕
                                </button>
                            </div>

                            <div style={styles.modalBody}>
                                {/* General explanation */}
                                <div style={styles.helpSection}>
                                    <h3 style={styles.helpSectionTitle}>1. Base columns</h3>
                                    <p style={styles.helpText}>
                                        For each task (row), you must provide:
                                    </p>
                                    <ul style={styles.helpList}>
                                        {studyInfo?.artifactCountPerTask && (
                                            <li>
                                                <code>artifact_1_filename</code> to{" "}
                                                <code>artifact_{studyInfo.artifactCountPerTask}_filename</code> — file names
                                                exactly as they appear inside the ZIP (e.g. <code>artifact1.java</code>).
                                            </li>
                                        )}
                                        <li>
                                            <code>question</code> — the task question shown to participants.
                                        </li>
                                        <li>
                                            <code>description</code> — optional helper text for the task.
                                        </li>
                                    </ul>
                                </div>

                                {/* Criterion-based explanation */}
                                <div style={styles.helpSection}>
                                    <h3 style={styles.helpSectionTitle}>2. Criterion answer columns</h3>
                                    {sortedCriteria.length === 0 ? (
                                        <p style={styles.helpText}>
                                            This study has no criteria yet. Create criteria first, then CSV columns
                                            will follow the pattern{" "}
                                            <code>criterion_{"<priority>"}_{"<TYPE>"}_answer</code>
                                        </p>
                                    ) : (
                                        <p style={styles.helpText}>
                                            For each criterion you created, there is a matching column in the CSV:
                                            <br />
                                            <code>criterion_{"{priorityOrder}"}_{"{TYPE}"}_answer</code>
                                        </p>
                                    )}

                                    {sortedCriteria.map((crit) => renderCriterionHelpRow(crit))}
                                </div>

                                {/* CSV quoting note */}
                                <div style={styles.helpSection}>
                                    <h3 style={styles.helpSectionTitle}>3. About quotes and commas</h3>
                                    <ul style={styles.helpList}>
                                        <li>
                                            If your answer contains a comma (e.g. multi-select values like{" "}
                                            <code>A,B</code>), you <b>must wrap it in quotes</b>:{" "}
                                            <code>"A,B"</code>.
                                        </li>
                                        <li>
                                            <b>ALL correct answers must be wrapped in quotes</b> — even simple ones like
                                            <code>"A"</code>, <code>"3"</code>, <code>"42"</code>.
                                        </li>

                                        <li>
                                            To leave an answer empty, write <code>""</code> (empty quotes).
                                            Never leave the cell blank.
                                        </li>

                                        <li>
                                            Internally all answers are stored as strings, but the expected format
                                            depends on the criterion type (see above).
                                        </li>
                                    </ul>
                                </div>
                            </div>

                            <div style={styles.modalFooter}>
                                <button
                                    style={styles.modalCloseFooterButton}
                                    onClick={() => setIsHelpOpen(false)}
                                >
                                    Got it
                                </button>
                            </div>
                        </div>
                    </div>
                </>
            )}

            <style>
                {`
                @keyframes floatParticle {
                    0% { transform: translateY(0); opacity: .4; }
                    50% { opacity: 1; }
                    100% { transform: translateY(-120vh); opacity: 0; }
                }

                @keyframes modalPop {
                    0% { opacity: 0; transform: scale(0.9) translateY(8px); }
                    100% { opacity: 1; transform: scale(1) translateY(0); }
                }
                `}
            </style>
        </div>
    );
}

